const slug=s=>s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"");
const j=(x,s=200)=>new Response(JSON.stringify(x),{status:s,headers:{"content-type":"application/json","cache-control":"no-store"}});
export async function onRequestPost({request,env}){
 if(!env.PYOREX_DB)return j({error:"PYOREX_DB missing"},503);
 if(!env.HUB_INGEST_TOKEN)return j({error:"HUB_INGEST_TOKEN missing"},503);
 if(request.headers.get("authorization")!==`Bearer ${env.HUB_INGEST_TOKEN}`)return j({error:"unauthorized"},401);
 const db=env.PYOREX_DB;
 for(const o of DATA.opp){
   let c=await db.prepare("SELECT id FROM hub_companies WHERE lower(name)=lower(?) OR slug=?").bind(o.company,slug(o.company.replace(/\b(inc|corp|ltd|limited)\.?$/i,"").trim())).first();
   if(!c){await db.prepare("INSERT OR IGNORE INTO hub_companies(slug,name,company_type) VALUES(?,?,'junior')").bind(slug(o.company),o.company).run();c=await db.prepare("SELECT id FROM hub_companies WHERE slug=?").bind(slug(o.company)).first()}
   await db.prepare("INSERT OR IGNORE INTO hub_projects(slug,name,company_id,country,region,commodities,deposit_model,stage,status) VALUES(?,?,?,?,?,?,?,?,?)").bind(slug(o.project),o.project,c.id,o.country||"Peru",o.region||null,JSON.stringify(o.commodities||[]),o.deposit_model||null,o.stage||null,o.association_type||null).run();
 }
 for(const e of DATA.ev){
   const p=await db.prepare("SELECT id,company_id FROM hub_projects WHERE slug=?").bind(slug(e.project)).first(); if(!p)continue;
   const d=new Date(e.date+"T00:00:00Z"), fp=slug(`${e.project}-${e.date}-${e.title}`);
   await db.prepare("INSERT OR IGNORE INTO hub_events(fingerprint,project_id,company_id,event_date,year,quarter,event_type,title,summary,source_name,source_url,source_type,relevance) VALUES(?,?,?,?,?,?,?,?,?,?,?,'primary','material')").bind(fp,p.id,p.company_id,e.date,d.getUTCFullYear(),Math.floor(d.getUTCMonth()/3)+1,e.type,e.title,e.summary||"",e.source_name,e.source_url).run();
 }
 for(const s of DATA.src){
   const p=s.project?await db.prepare("SELECT id,company_id FROM hub_projects WHERE slug=?").bind(slug(s.project)).first():null;
   let cid=p?.company_id||null;if(!cid){const c=await db.prepare("SELECT id FROM hub_companies WHERE lower(name)=lower(?)").bind(s.company).first();cid=c?.id||null}
   await db.prepare("INSERT OR IGNORE INTO hub_sources(company_id,project_id,name,url,source_kind,enabled) VALUES(?,?,?,?,?,?)").bind(cid,p?.id||null,s.company,s.url,s.source_kind||"company_news",s.enabled===false?0:1).run();
 }
 await db.prepare("UPDATE hub_projects SET last_material_update_at=(SELECT MAX(event_date) FROM hub_events WHERE project_id=hub_projects.id),updated_at=CURRENT_TIMESTAMP").run();
 const counts=await db.prepare("SELECT (SELECT COUNT(*) FROM hub_companies) companies,(SELECT COUNT(*) FROM hub_projects) projects,(SELECT COUNT(*) FROM hub_events) events,(SELECT COUNT(*) FROM hub_sources) sources").first();
 return j({status:"success",...counts});
}